package com.berling.marketplace.utils\n\nimport android.app.NotificationChannel\nimport android.app.NotificationManager\nimport android.content.Context\nimport android.os.Build\nimport androidx.core.app.NotificationCompat\nimport kotlinx.serialization.Serializable\n\n/**\n * NotificationManager handles push notifications and in-app notifications\n * Manages notifications for reviews, replies, messages, and report status\n */\nclass NotificationManager(private val context: Context) {\n\n    private val notificationManager = context.getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager\n    private val channelId = \"marketplace_notifications\"\n    private var notificationId = 1000\n\n    init {\n        createNotificationChannels()\n    }\n\n    /**\n     * Create notification channels for different notification types\n     */\n    private fun createNotificationChannels() {\n        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {\n            // Messages channel\n            val messagesChannel = NotificationChannel(\n                \"messages\",\n                \"Messages\",\n                NotificationManager.IMPORTANCE_HIGH\n            ).apply {\n                description = \"Notifications for new messages\"\n                enableVibration(true)\n                enableLights(true)\n            }\n            notificationManager.createNotificationChannel(messagesChannel)\n\n            // Reviews channel\n            val reviewsChannel = NotificationChannel(\n                \"reviews\",\n                \"Reviews\",\n                NotificationManager.IMPORTANCE_DEFAULT\n            ).apply {\n                description = \"Notifications for new reviews and replies\"\n                enableVibration(true)\n            }\n            notificationManager.createNotificationChannel(reviewsChannel)\n\n            // System channel\n            val systemChannel = NotificationChannel(\n                \"system\",\n                \"System\",\n                NotificationManager.IMPORTANCE_LOW\n            ).apply {\n                description = \"System notifications\"\n            }\n            notificationManager.createNotificationChannel(systemChannel)\n        }\n    }\n\n    /**\n     * Show notification for new message\n     */\n    fun showMessageNotification(\n        senderName: String,\n        messagePreview: String,\n        conversationId: String\n    ) {\n        val notification = NotificationCompat.Builder(context, \"messages\")\n            .setSmallIcon(android.R.drawable.ic_dialog_email)\n            .setContentTitle(\"New message from $senderName\")\n            .setContentText(messagePreview)\n            .setAutoCancel(true)\n            .setPriority(NotificationCompat.PRIORITY_HIGH)\n            .setCategory(NotificationCompat.CATEGORY_MESSAGE)\n            .build()\n\n        notificationManager.notify(notificationId++, notification)\n    }\n\n    /**\n     * Show notification for new review\n     */\n    fun showReviewNotification(\n        buyerName: String,\n        productTitle: String,\n        rating: Int\n    ) {\n        val stars = \"⭐\".repeat(rating)\n        val notification = NotificationCompat.Builder(context, \"reviews\")\n            .setSmallIcon(android.R.drawable.ic_dialog_info)\n            .setContentTitle(\"New review from $buyerName\")\n            .setContentText(\"$stars - $productTitle\")\n            .setAutoCancel(true)\n            .setPriority(NotificationCompat.PRIORITY_DEFAULT)\n            .setCategory(NotificationCompat.CATEGORY_SOCIAL)\n            .build()\n\n        notificationManager.notify(notificationId++, notification)\n    }\n\n    /**\n     * Show notification for review reply\n     */\n    fun showReviewReplyNotification(\n        replierName: String,\n        replyPreview: String\n    ) {\n        val notification = NotificationCompat.Builder(context, \"reviews\")\n            .setSmallIcon(android.R.drawable.ic_dialog_info)\n            .setContentTitle(\"New reply from $replierName\")\n            .setContentText(replyPreview)\n            .setAutoCancel(true)\n            .setPriority(NotificationCompat.PRIORITY_DEFAULT)\n            .setCategory(NotificationCompat.CATEGORY_SOCIAL)\n            .build()\n\n        notificationManager.notify(notificationId++, notification)\n    }\n\n    /**\n     * Show notification for report status update\n     */\n    fun showReportStatusNotification(\n        reportType: String,\n        status: String\n    ) {\n        val message = when (status) {\n            \"approved\" -> \"Your report has been reviewed and action has been taken.\"\n            \"rejected\" -> \"Your report was reviewed but no action was taken.\"\n            else -> \"Your report is being reviewed.\"\n        }\n\n        val notification = NotificationCompat.Builder(context, \"system\")\n            .setSmallIcon(android.R.drawable.ic_dialog_info)\n            .setContentTitle(\"Report Status Update\")\n            .setContentText(message)\n            .setAutoCancel(true)\n            .setPriority(NotificationCompat.PRIORITY_DEFAULT)\n            .build()\n\n        notificationManager.notify(notificationId++, notification)\n    }\n\n    /**\n     * Show notification for follow\n     */\n    fun showFollowNotification(followerName: String) {\n        val notification = NotificationCompat.Builder(context, \"system\")\n            .setSmallIcon(android.R.drawable.ic_dialog_info)\n            .setContentTitle(\"New follower\")\n            .setContentText(\"$followerName started following you\")\n            .setAutoCancel(true)\n            .setPriority(NotificationCompat.PRIORITY_DEFAULT)\n            .setCategory(NotificationCompat.CATEGORY_SOCIAL)\n            .build()\n\n        notificationManager.notify(notificationId++, notification)\n    }\n\n    /**\n     * Show notification for product sold\n     */\n    fun showProductSoldNotification(productTitle: String) {\n        val notification = NotificationCompat.Builder(context, \"system\")\n            .setSmallIcon(android.R.drawable.ic_dialog_info)\n            .setContentTitle(\"Product Sold\")\n            .setContentText(\"Your product '$productTitle' has been sold\")\n            .setAutoCancel(true)\n            .setPriority(NotificationCompat.PRIORITY_DEFAULT)\n            .build()\n\n        notificationManager.notify(notificationId++, notification)\n    }\n\n    /**\n     * Show notification for ban\n     */\n    fun showBanNotification(reason: String) {\n        val notification = NotificationCompat.Builder(context, \"system\")\n            .setSmallIcon(android.R.drawable.ic_dialog_alert)\n            .setContentTitle(\"Account Suspended\")\n            .setContentText(reason)\n            .setAutoCancel(true)\n            .setPriority(NotificationCompat.PRIORITY_HIGH)\n            .build()\n\n        notificationManager.notify(notificationId++, notification)\n    }\n\n    /**\n     * Show notification for KYC requirement\n     */\n    fun showKYCRequiredNotification(productTitle: String) {\n        val notification = NotificationCompat.Builder(context, \"system\")\n            .setSmallIcon(android.R.drawable.ic_dialog_info)\n            .setContentTitle(\"KYC Verification Required\")\n            .setContentText(\"Complete verification to sell items over \\$1000\")\n            .setAutoCancel(true)\n            .setPriority(NotificationCompat.PRIORITY_DEFAULT)\n            .build()\n\n        notificationManager.notify(notificationId++, notification)\n    }\n\n    /**\n     * Cancel notification\n     */\n    fun cancelNotification(notificationId: Int) {\n        notificationManager.cancel(notificationId)\n    }\n\n    /**\n     * Cancel all notifications\n     */\n    fun cancelAllNotifications() {\n        notificationManager.cancelAll()\n    }\n}\n\n@Serializable\ndata class NotificationEvent(\n    val id: String,\n    val type: String, // message, review, reply, follow, report_status, ban, kyc\n    val title: String,\n    val message: String,\n    val sourceId: String? = null,\n    val timestamp: Long = System.currentTimeMillis(),\n    val isRead: Boolean = false,\n    val actionUrl: String? = null\n)\n\ndata class NotificationConfig(\n    val enableMessageNotifications: Boolean = true,\n    val enableReviewNotifications: Boolean = true,\n    val enableFollowNotifications: Boolean = true,\n    val enableSystemNotifications: Boolean = true,\n    val soundEnabled: Boolean = true,\n    val vibrationEnabled: Boolean = true,\n    val lightEnabled: Boolean = true\n)\n
